{
  "contract": "SimpleSalesEth",
  "closure": {
    "site_function": "buy",
    "site_call": ".safeTransferFrom",
    "functions": [
      "withdrawAllFailedCredits"
    ],
    "justification": "withdrawAllFailedCredits modifies the exposed storage variables _ethBal and failedTransferCredits."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "withdrawAllFailedCredits"
    ],
    "nesting_bound": {
      "withdrawAllFailedCredits": 1
    }
  },
  "phases": {
    "function": "buy",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before .safeTransferFrom"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before .safeTransferFrom",
      "to_marker": "after .safeTransferFrom"
    },
    "post": {
      "name": "post",
      "from_marker": "after .safeTransferFrom",
      "to_marker": "exit"
    },
    "linearization_point": "after .safeTransferFrom"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of ETH in-flight during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum_failedTransferCredits == _ethBal + inFlight",
    "stable_formula": "_sum_failedTransferCredits == _ethBal",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum_failedTransferCredits <= _ethBal",
    "rule": "The exposure invariant ensures that the sum of failedTransferCredits is conserved across the callback window, accounting for in-flight ETH."
  }
}
